<main class="container py-4" style="max-width:800px"><h1 class="h3 mb-4"><?= html_escape($label); ?></h1><div class="card border-0 shadow-sm"><div class="card-body p-4"><?= validation_errors('<div class="alert alert-danger">', '</div>'); ?><?= form_open($item?'sistem-nilai/master-data/'.$type.'/perbarui/'.$item->id:'sistem-nilai/master-data/'.$type.'/simpan'); ?><?php if($type==='tahun-akademik'): ?><div class="row g-3"><div class="col-md-6"><label class="form-label">Tahun</label><input required class="form-control" name="tahun" maxlength="9" value="<?= set_value('tahun',$item?$item->tahun:''); ?>"></div><div class="col-md-6"><label class="form-label">Semester</label><select name="semester" class="form-select"><?php foreach(['Ganjil','Genap'] as $x): ?><option <?= set_value('semester',$item?$item->semester:'')===$x?'selected':''; ?>><?= $x; ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Tanggal Mulai</label><input type="date" class="form-control" name="tanggal_mulai" value="<?= set_value('tanggal_mulai',$item?$item->tanggal_mulai:''); ?>"></div><div class="col-md-6"><label class="form-label">Tanggal Selesai</label><input type="date" class="form-control" name="tanggal_selesai" value="<?= set_value('tanggal_selesai',$item?$item->tanggal_selesai:''); ?>"></div><div class="col-md-6"><label class="form-label">Status</label><select name="status" class="form-select"><?php foreach(['Draft','Aktif','Selesai'] as $x): ?><option <?= set_value('status',$item?$item->status:'Draft')===$x?'selected':''; ?>><?= $x; ?></option><?php endforeach; ?></select></div></div><?php elseif($type==='mata-kuliah'): ?><div class="row g-3"><div class="col-md-4"><label class="form-label">Kode MK</label><input required class="form-control" name="kode_mk" value="<?= set_value('kode_mk',$item?$item->kode_mk:''); ?>"></div><div class="col-md-8"><label class="form-label">Nama Mata Kuliah</label><input required class="form-control" name="nama_mk" value="<?= set_value('nama_mk',$item?$item->nama_mk:''); ?>"></div><div class="col-md-3"><label class="form-label">SKS</label><input required min="1" type="number" class="form-control" name="sks" value="<?= set_value('sks',$item?$item->sks:''); ?>"></div><div class="col-md-3"><label class="form-label">Semester</label><input required min="1" type="number" class="form-control" name="semester" value="<?= set_value('semester',$item?$item->semester:''); ?>"></div><div class="col-md-3"><label class="form-label">Jenis</label><select name="jenis" class="form-select"><?php foreach(['Wajib','Pilihan'] as $x): ?><option <?= set_value('jenis',$item?$item->jenis:'Wajib')===$x?'selected':''; ?>><?= $x; ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Status</label><select name="status" class="form-select"><?php foreach(['Aktif','Nonaktif'] as $x): ?><option <?= set_value('status',$item?$item->status:'Aktif')===$x?'selected':''; ?>><?= $x; ?></option><?php endforeach; ?></select></div></div><?php else: ?><div class="mb-3"><label class="form-label">Mata Kuliah</label><select required name="mata_kuliah_id" class="form-select"><option value="">Pilih</option><?php foreach($mata_kuliah as $x): ?><option value="<?= $x->id; ?>" <?= set_value('mata_kuliah_id',$item?$item->mata_kuliah_id:'')==$x->id?'selected':''; ?>><?= html_escape($x->kode_mk.' — '.$x->nama_mk); ?></option><?php endforeach; ?></select></div><div class="mb-3"><label class="form-label">Tahun Akademik</label><select required name="tahun_akademik_id" class="form-select"><option value="">Pilih</option><?php foreach($tahun_akademik as $x): ?><option value="<?= $x->id; ?>" <?= set_value('tahun_akademik_id',$item?$item->tahun_akademik_id:'')==$x->id?'selected':''; ?>><?= html_escape($x->tahun.' / '.$x->semester); ?></option><?php endforeach; ?></select></div><?php endif; ?><div class="mt-4"><button class="btn btn-success">Simpan</button><a class="btn btn-outline-secondary" href="<?= site_url('sistem-nilai/master-data/'.$type); ?>">Batal</a></div><?= form_close(); ?></div></div></main>
